style.content:
/* Switch off the native look of the closed control */
select {
  appearance: none;
  width: 100%;
  min-height: 3.6rem;
  padding: 0.4rem 2.6rem 0.4rem 0.8rem;
  font: inherit;
  color: inherit;
  background: #fff url("https://stepan-fielmann.github.io/wey/images/arrow.svg") no-repeat right 1rem center;
  border: 1px solid #cbc4b4;
  border-radius: 0.8rem;
  cursor: pointer;
}

select:focus {
  outline: none;
  border-color: #4636c9;
  box-shadow: 0 0 0 3px #eceaff;
}

/* The list that opens is drawn by the browser and the OS:
   text only, no layout, almost no styles */

style.hiddenContent:
/* Preview frame shared by every view (from Lunch and Learn Simple's simple.css).
   Nothing in here is part of any demo. */
:root {
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: clamp(15px, 0.55vw + 9px, 21px);
  color: #1c1b22;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
}

:focus-visible {
  outline: 3px solid #1f6feb;
  outline-offset: 2px;
}

/* The demo area fills the preview. */
.stage {
  position: relative;
  height: 100vh;
  overflow: hidden;
  background: #fff;
}

/* Note shown by unsupported.js when the browser lacks the feature. */
.unsupported {
  position: absolute;
  left: 0.8rem;
  bottom: 0.8rem;
  z-index: 100;
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
  max-width: min(26rem, calc(100% - 1.6rem));
  margin: 0;
  padding: 0.35rem 0.75rem;
  font-size: 0.72rem;
  line-height: 1.4;
  color: #b42318;
  background: rgb(253 233 230 / 0.95);
  border: 1px solid #f1b8b0;
  border-radius: 0.6rem;
  pointer-events: none;
}

.unsupported::before {
  content: '';
  flex: none;
  width: 0.45rem;
  height: 0.45rem;
  background: #e5372b;
  border-radius: 50%;
}

.unsupported b {
  color: #8f1d14;
}

/* Page and option-content looks only, shared by before and after.
   The control itself is styled on each page, in the code that is shown. */

.stage {
  display: grid;
  place-items: start center;
  padding-top: 4rem;
  background: #f8f6f1;
}

.field {
  width: 24rem;
  padding: 1.4rem 1.5rem 1.6rem;
  background: #fff;
  border: 1px solid #e4dfd4;
  border-radius: 1.1rem;
  box-shadow: 0 20px 50px -30px rgb(28 27 34 / 0.5);
}

.field-control {
  position: relative;
}

.field-control + .field-control {
  margin-top: 1.2rem;
}

.field label {
  display: block;
  margin-bottom: 0.4rem;
  font-weight: 700;
}

/* A person: avatar, name, role (inside options and the closed control) */
.field img {
  grid-row: span 2;
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 50%;
}

.field small {
  grid-column: 2;
  font-size: 0.8rem;
  color: #77748a;
}

/* The separator inside <small> is only there for the plain native select, which shows the
   option's text ("Ava Lindqvist · Design lead"). Where the select is customizable, the role
   gets its own line and the separator is in the way. */
.field small span {
  display: none;
}
